+import prismaMock from '../prisma-mock';
+import {
+  ARTICLE_LIST_DEFAULT_LIMIT,
+  ARTICLE_LIST_MAX_LIMIT,
+  getArticles,
+} from '../../app/routes/article/article.service';
+
+describe('ArticleService list limit', () => {
+  beforeEach(() => {
+    // @ts-ignore
+    prismaMock.article.count.mockResolvedValue(0);
+    // @ts-ignore
+    prismaMock.article.findMany.mockResolvedValue([]);
+  });
+
+  test('should use a maximum of 50 articles per request', () => {
+    // Then
+    expect(ARTICLE_LIST_MAX_LIMIT).toBe(50);
+  });
+
+  test('should use a default of 10 articles when no limit is sent', () => {
+    // Then
+    expect(ARTICLE_LIST_DEFAULT_LIMIT).toBe(10);
+  });
+
+  test('should pass a limit below the maximum to Prisma unchanged', async () => {
+    // Given
+    const query = { limit: '20' };
+
+    // When
+    await getArticles(query);
+
+    // Then
+    expect(prismaMock.article.findMany).toHaveBeenLastCalledWith(
+      expect.objectContaining({ take: 20 }),
+    );
+  });
+
+  test('should allow a limit equal to the maximum', async () => {
+    // Given
+    const query = { limit: String(ARTICLE_LIST_MAX_LIMIT) };
+
+    // When
+    await getArticles(query);
+
+    // Then
+    expect(prismaMock.article.findMany).toHaveBeenLastCalledWith(
+      expect.objectContaining({ take: 50 }),
+    );
+  });
+
+  test('should clamp a limit above the maximum to 50', async () => {
+    // Given
+    const query = { limit: '500' };
+
+    // When
+    await getArticles(query);
+
+    // Then
+    expect(prismaMock.article.findMany).toHaveBeenLastCalledWith(
+      expect.objectContaining({ take: 50 }),
+    );
+  });
+
+  test('should use the default of 10 when no limit is sent', async () => {
+    // Given
+    const query = {};
+
+    // When
+    await getArticles(query);
+
+    // Then
+    expect(prismaMock.article.findMany).toHaveBeenLastCalledWith(
+      expect.objectContaining({ take: 10 }),
+    );
+  });
+
+  test('should use the default of 10 when the limit is not a number', async () => {
+    // Given
+    const query = { limit: 'abc' };
+
+    // When
+    await getArticles(query);
+
+    // Then
+    expect(prismaMock.article.findMany).toHaveBeenLastCalledWith(
+      expect.objectContaining({ take: 10 }),
+    );
+  });
+});
